1	/* A small, state-driven pub. All essential interactions also live in the DOM. */
2	(function (root) {
3	  'use strict';
4	  class PubScene {
5	    constructor(canvas) {
6	      this.canvas = canvas;
7	      this.ctx = canvas.getContext('2d');
8	      this.reduced = matchMedia('(prefers-reduced-motion: reduce)');
9	      const scale = Math.min(devicePixelRatio || 1, 1.5);
10	      canvas.width = 1100 * scale;
11	      canvas.height = 640 * scale;
12	      this.ctx.scale(scale, scale);
13	    }
14	    rect(x,y,w,h,color) { this.ctx.fillStyle=color; this.ctx.fillRect(x,y,w,h); }
15	    ellipse(x,y,rx,ry,color) { const c=this.ctx;c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill(); }
16	    line(points,color,width=1) { const c=this.ctx;c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.stroke(); }
17	    poly(points,color) { const c=this.ctx;c.fillStyle=color;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fill(); }
18	    ring(x,y,r,color,width=2) { const c=this.ctx;c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke(); }
19	    text(value,x,y,size,color,font='Georgia',align='center') { const c=this.ctx;c.font=`${size}px ${font}`;c.fillStyle=color;c.textAlign=align;c.fillText(value,x,y); }
20	    bottle(x,y,color,scale=1) { const c=this.ctx;c.save();c.translate(x,y);c.scale(scale,scale);this.rect(-5,-43,10,13,color);this.rect(-9,-31,18,31,color);this.rect(-4,-44,8,3,'#cfa762');this.rect(-7,-20,14,13,'#ddcf98');this.rect(-4,-36,2,9,'#ffffff25');this.rect(-6,-27,2,21,'#ffffff15');this.text('TK',0,-10,7,'#3e4933');c.restore(); }
21	    // Transform-free variant for signs drawn inside the already-transformed
22	    // city camera, so the active camera matrix is never overwritten mid-frame.
23	    bottleAt(x,y,color,s=1){const r=(dx,dy,w,h,col)=>this.rect(x+dx*s,y+dy*s,w*s,h*s,col);r(-5,-43,10,13,color);r(-9,-31,18,31,color);r(-4,-44,8,3,'#cfa762');r(-7,-20,14,13,'#ddcf98');r(-4,-36,2,9,'#ffffff25');r(-6,-27,2,21,'#ffffff15');this.text('TK',x,y-10*s,7*s,'#3e4933');}
24	    tulips(x,y,bouquet,size=1) {
25	      const colors=bouquet.palette==='cool'?['#aa9dc4','#c7c0d6','#897aa7']:bouquet.palette==='warm'?['#ce815d','#e2b864','#bf6555']:['#cc8068','#b6a4c4','#dfbb6d'];
26	      for(let i=0;i<5;i++){
27	        const fx=x+(i-2)*5*size,fy=y-(21+i%3*4)*size;
28	        this.line([[x,y],[fx,fy]],'#52724c',1.6*size);
29	        this.ellipse(fx-3*size,fy+9*size,3*size,6*size,'#729363');
30	        this.ellipse(fx,fy,4*size,5*size,colors[i%3]);
31	        this.ellipse(fx-2.5*size,fy-2*size,2*size,4*size,colors[i%3]);
32	        this.ellipse(fx+2.5*size,fy-2*size,2*size,4*size,colors[i%3]);
33	      }
34	      if(bouquet.wrap==='paper'){
35	        const c=this.ctx;c.fillStyle='#dcc7a0';c.beginPath();c.moveTo(x-11*size,y-12*size);c.lineTo(x+11*size,y-12*size);c.lineTo(x+4*size,y+4*size);c.lineTo(x-4*size,y+4*size);c.closePath();c.fill();
36	        this.line([[x-10*size,y-11*size],[x+3*size,y+3*size]],'#ae9976',size);
37	      }else{
38	        this.line([[x-5*size,y-4*size],[x+5*size,y-4*size]],'#be846f',3*size);
39	        this.line([[x,y-4*size],[x-7*size,y+3*size],[x-8*size,y-3*size],[x,y-4*size],[x+8*size,y-3*size],[x+7*size,y+3*size]],'#dfb19a',1.5*size);
40	      }
41	    }
42	    bicycle(bike,bouquet) {
43	      const x=bike.x,y=bike.y;
44	      this.ellipse(x,y+11,30,6,'#1c434044');
45	      for(const wx of [x-15,x+15]){this.ellipse(wx,y+7,10,10,'#283f3d');this.ellipse(wx,y+7,7,7,'#a8b6a0');this.ellipse(wx,y+7,5.5,5.5,'#657d70');}
46	      this.line([[x-15,y+7],[x-6,y-7],[x+3,y+7],[x-15,y+7],[x+8,y-8],[x+15,y+7]],'#bb8254',3);
47	      this.line([[x+8,y-8],[x+9,y-16],[x+17,y-16]],'#d7c49b',2);
48	      this.line([[x-11,y-9],[x-2,y-9]],'#35433b',3);
49	      this.rect(x+16,y-12,16,11,'#b2986e');this.line([[x+16,y-12],[x+32,y-12],[x+29,y-1],[x+18,y-1],[x+16,y-12]],'#dec89a',1.5);
50	      for(let i=0;i<3;i++)this.line([[x+19+i*4,y-11],[x+20+i*3,y-2]],'#7f7857',1);
51	      if(bouquet&&bouquet.stored)this.tulips(x+24,y-8,bouquet,.65);
52	    }
53	    cityWorldPoint(x,y) {
54	      const view=this.cityTransform||{scale:1,tx:0,ty:0};
55	      return {x:(x-view.tx)/view.scale,y:(y-view.ty)/view.scale};
56	    }
57	    // Deterministic integer hash: fixed stone/water accents per cell, never Math.random.
58	    cityRand(seed){let z=(Math.imul(seed|0,2654435761)^0x9e3779b9)>>>0;z=Math.imul(z^(z>>>16),2246822519)>>>0;z^=z>>>13;return((z^0x68bc9a41)>>>0)/4294967296;}
59	    // Warm cut-stone coping frames a cool, tonally banded canal. Footprints
60	    // (land, water, crossings) are unchanged; this is rendering only.
61	    drawQuayWater(w,night,t){
62	      const P=this.cityPalette,horizontal=w.w>=w.h;
63	      this.rect(w.x-7,w.y-7,w.w+14,w.h+14,night?'#b3a683':'#dccfaa');
64	      const cap=night?'#8f886d':'#c0b18b';
65	      if(horizontal){
66	        this.rect(w.x-7,w.y-7,w.w+14,6,cap);this.rect(w.x-7,w.y+w.h+1,w.w+14,6,cap);
67	        for(let qx=w.x+18;qx<w.x+w.w-6;qx+=26){
68	          this.line([[qx,w.y-6],[qx,w.y-1]],night?'#00000026':'#7a6c4c2b',1);
69	          this.line([[qx,w.y+w.h+2],[qx,w.y+w.h+6]],night?'#00000026':'#7a6c4c2b',1);
70	        }
71	      }else{
72	        this.rect(w.x-7,w.y-7,6,w.h+14,cap);this.rect(w.x+w.w+1,w.y-7,6,w.h+14,cap);
73	        for(let qy=w.y+18;qy<w.y+w.h-6;qy+=26){
74	          this.line([[w.x-6,qy],[w.x-1,qy]],night?'#00000026':'#7a6c4c2b',1);
75	          this.line([[w.x+w.w+2,qy],[w.x+w.w+6,qy]],night?'#00000026':'#7a6c4c2b',1);
76	        }
77	      }
78	      this.rect(w.x,w.y,w.w,w.h,night?'#235d6c':P.CANAL_BLUE);
79	      // Limited tonal bands and a few restrained static highlights read as water.
80	      if(horizontal){
81	        this.rect(w.x,w.y+Math.round(w.h*.24),w.w,Math.max(3,Math.round(w.h*.13)),night?'#1b4855':'#2c7d89');
82	        this.rect(w.x,w.y+Math.round(w.h*.6),w.w,Math.max(2,Math.round(w.h*.08)),night?'#ffffff14':'#d8eef022');
83	        for(let k=0;k<3;k++){
84	          const hx=w.x+24+this.cityRand(w.x+k*97+3)*(w.w-80);
85	          const hy=w.y+8+this.cityRand(w.y+k*53+9)*(w.h-18);
86	          this.line([[hx,hy],[hx+20+this.cityRand(k+w.y+5)*18,hy]],night?'#d6ece816':'#ffffff26',1.4);
87	        }
88	      }else{
89	        this.rect(w.x+Math.round(w.w*.24),w.y,Math.max(3,Math.round(w.w*.13)),w.h,night?'#1b4855':'#2c7d89');
90	        this.rect(w.x+Math.round(w.w*.62),w.y,Math.max(2,Math.round(w.w*.09)),w.h,night?'#ffffff14':'#d8eef022');
91	        for(let k=0;k<2;k++){
92	          const vx=w.x+8+this.cityRand(w.x+k*61+4)*(w.w-16);
93	          const vy=w.y+24+this.cityRand(w.y+k*43+7)*(w.h-70);
94	          this.line([[vx,vy],[vx,vy+22+this.cityRand(k+w.x+3)*20]],night?'#d6ece816':'#ffffff26',1.4);
95	        }
96	      }
97	      // Cool shadow where the water surface meets the stone edge.
98	      this.rect(w.x,w.y,w.w,3,night?'#0a2029bb':'#1139445e');
99	      this.rect(w.x,w.y+w.h-3,w.w,3,night?'#0a2029bb':'#1139445e');
100	      this.rect(w.x,w.y,3,w.h,night?'#0a202977':'#11394433');
101	      this.rect(w.x+w.w-3,w.y,3,w.h,night?'#0a202977':'#11394433');
102	      const flecks=Math.floor(w.w*w.h/1500);
103	      for(let i=0;i<flecks;i++){
104	        const fx=w.x+((i*41+t*5)%Math.max(1,w.w-16)),fy=w.y+(i*59)%w.h;
105	        this.rect(fx,fy,13,2,night?'#d9ecea24':'#eef7ee33');
106	      }
107	    }
108	    drawCity(view,time) {
109	      const C=window.City,c=this.ctx,night=!!view.afterHours;
110	      // Overview (zoom 1/2) keeps the whole-city map; the close street camera
111	      // follows the avatar at ~2.6x the overview scale.
112	      const street=view.camera==='street';
113	      const base=Math.min(1100/C.WIDTH,640/C.HEIGHT);
114	      const scale=base*(street?2.6:(view.zoom||1));
115	      const spanW=1100/scale,spanH=640/scale;
116	      const tx=scale*C.WIDTH<=1100?(1100-scale*C.WIDTH)/2:-Math.max(0,Math.min(C.WIDTH-spanW,view.position.x-spanW/2))*scale;
117	      const ty=scale*C.HEIGHT<=640?(640-scale*C.HEIGHT)/2:-Math.max(0,Math.min(C.HEIGHT-spanH,view.position.y-spanH/2))*scale;
118	      this.cityTransform={scale,tx,ty};
119	      const INK='#183b48',CANAL_BLUE='#378e9b',BRICK='#b86b4c',SAND='#e2d4b0',LAMP='#ffd184',SLATE='#253d49';
120	      // Stone/path/coping/water tones keep quay, street and canal distinct.
121	      const STONE=night?'#ab9f80':'#d6c9a6';
122	      const PATH=night?'#bdb18f':'#e4d8b5';
123	      const QUAY=night?'#8f886c':'#bfb08c';
124	      this.cityPalette={INK,CANAL_BLUE,BRICK,SAND,LAMP,SLATE};
125	      // Reduced-motion frames at a fixed view must be identical for every time.
126	      const t=(this.reduced&&this.reduced.matches)?0:time;
127	      c.clearRect(0,0,1100,640);this.rect(0,0,1100,640,night?'#102733':INK);
128	      c.save();c.translate(tx,ty);c.scale(scale,scale);
129	      this.rect(0,0,C.WIDTH,C.HEIGHT,night?'#123745':'#23505c');
130	      for(let i=0;i<80;i++)this.rect((i*139+t*9)%C.WIDTH,(i*83)%C.HEIGHT,20+i%4*13,2,night?'#9fc3c018':'#b9d6bd20');
131	      const land=C.LAND;this.rect(land.x-7,land.y-7,land.w+14,land.h+14,night?'#6f6c54':'#9b906f');this.rect(land.x,land.y,land.w,land.h,STONE);
132	      this.line([[land.x,land.y+1],[land.x+land.w,land.y+1]],night?'#fff4d618':'#fff6df24',1);
133	      // Street surfaces are clipped at canals. Crossings are drawn separately.
134	      c.save();c.beginPath();c.rect(land.x,land.y,land.w,land.h);c.clip();
135	      // Sparse scattered cut-stone seams: deterministic and subordinate to paths.
136	      for(let gx=0;gx<Math.round(land.w/58);gx++)for(let gy=0;gy<Math.round(land.h/58);gy++){
137	        const k=gx*73+gy*131+7;
138	        if(this.cityRand(k)>0.26)continue;
139	        const jx=land.x+gx*58+8+Math.floor(this.cityRand(k+1)*36);
140	        const jy=land.y+gy*58+8+Math.floor(this.cityRand(k+2)*36);
141	        this.line(this.cityRand(k+3)>.5?[[jx,jy],[jx+9,jy]]:[[jx,jy],[jx,jy+9]],night?'#00000026':'#8a7c5822',1);
142	      }
143	      for(const x of [190,390,590,890,1190,1490,1650]){this.rect(x-19,40,38,1040,PATH);this.line([[x,40],[x,1080]],night?'#9c9272':'#c1b48e',1);}
144	      for(const y of [270,520,690,890,1040]){this.rect(70,y-18,1660,36,PATH);this.line([[70,y],[1730,y]],night?'#9c9272':'#c1b48e',1);}
145	      // Small public greens give the quays room to breathe.
146	      for(const park of [{x:92,y:64,w:260,h:158},{x:1160,y:530,w:220,h:155},{x:150,y:860,w:215,h:140}]){
147	        this.rect(park.x,park.y,park.w,park.h,'#84966b');
148	        this.line([[park.x+15,park.y+park.h/2],[park.x+park.w-15,park.y+park.h/2]],'#c4bd91',13);
149	        for(let i=0;i<8;i++){const x=park.x+25+(i%4)*(park.w-50)/3,y=park.y+25+Math.floor(i/4)*(park.h-50);this.ellipse(x+4,y+6,15,18,'#425a4845');this.ellipse(x,y,14,19,i%2?'#527655':'#6c865c');this.ellipse(x-4,y-5,8,11,'#94a776');}
150	      }
151	      c.restore();
152	      for(const water of C.WATERS)this.drawQuayWater(water,night,t);
153	      // Wide district lettering belongs to the overview; the close street view
154	      // keeps labels sparse so facades, the route and doors stay dominant.
155	      if(!street){
156	        this.text('H E T   I J',460,393,26,'#c2d6be80','Georgia');
157	        this.text('NOORD',1260,67,27,'#405b4b','Georgia');this.text('JORDAAN',285,490,24,'#52624a','Georgia');
158	        this.text('CENTRUM',770,503,21,'#687056','Georgia');this.text('DE PIJP',865,862,25,'#52624a','Georgia');this.text('SCIENCE PARK',1445,865,20,'#52624a','Georgia');
159	      }
160	      for(const crossing of C.CROSSINGS){
161	        if(crossing.kind==='ferry'){
162	          c.setLineDash([7,9]);this.line([[crossing.x+crossing.w/2,crossing.y],[crossing.x+crossing.w/2,crossing.y+crossing.h]],'#e8d6a3',3);c.setLineDash([]);
163	          for(const y of [crossing.y,crossing.y+crossing.h-13]){this.rect(crossing.x-15,y,crossing.w+30,13,'#736c4b');this.rect(crossing.x-15,y+2,crossing.w+30,2,'#d4bd87');}
164	          this.text('免费渡轮',crossing.x+crossing.w+10,crossing.y+100,17,'#e4d8ac','sans-serif','left');
165	        }else{
166	          // Worn timber deck inside the unchanged crossing footprint; stone
167	          // abutments and fascia give the bridge depth without a new crossing.
168	          const g=crossing.x,top=crossing.y,gw=crossing.w,gh=crossing.h,horizontal=gw>gh;
169	          this.rect(g,top,gw,gh,'#b8ab84');
170	          if(horizontal){
171	            this.rect(g-4,top+2,4,gh-4,QUAY);this.rect(g+gw,top+2,4,gh-4,QUAY);
172	            this.rect(g,top,gw,4,'#63705b');this.rect(g,top+gh-4,gw,4,'#45503e');
173	            this.rect(g+3,top+5,gw-6,1.6,'#ffffff1a');
174	            for(let px=g+14;px<g+gw-8;px+=18)this.line([[px,top+6],[px,top+gh-6]],'#0000001a',1);
175	          }else{
176	            this.rect(g+2,top-4,gw-4,4,QUAY);this.rect(g+2,top+gh,gw-4,4,QUAY);
177	            this.rect(g,top,4,gh,'#63705b');this.rect(g+gw-4,top,4,gh,'#45503e');
178	            this.rect(g+5,top+3,1.6,gh-6,'#ffffff1a');
179	            for(let py=top+14;py<top+gh-8;py+=18)this.line([[g+6,py],[g+gw-6,py]],'#0000001a',1);
180	          }
181	        }
182	      }
183	      // Intentional 2.5D canal facades: shadow, side depth, tall windows,
184	      // stepped/pitched roofs and a readable real door on every destination.
185	      this.drawHouses(C,view,night,t);
186	      // Lotte rehearses on the narrow bridge just east of the pub: a visible
187	      // musician with a guitar marks the bridge meeting point (not a door).
188	      this.drawBridgeMusician(516,624,night,t,street);
189	      // Working boats and cranes distinguish the north bank from the café streets.
190	      this.line([[1310,285],[1310,209],[1370,209]],'#b99756',7);this.line([[1310,234],[1360,209]],'#b99756',3);this.line([[1368,211],[1368,250]],'#405d51',2);
191	      for(const mooring of [{x:1090,y:374},{x:480,y:735},{x:1080,y:568}]){this.ellipse(mooring.x,mooring.y,12,29,'#244e53');this.ellipse(mooring.x,mooring.y-2,9,24,'#af9060');this.rect(mooring.x-6,mooring.y-8,12,16,'#d5c49b');}
192	      for(let i=0;i<9;i++){const x=155+(i*157)%1500,y=260+(i%3)*215;if(C.walkable(x,y)){this.ellipse(x,y+4,5,4,'#43594444');this.rect(x-3,y-3,6,10,['#728465','#977550','#596f73'][i%3]);this.ellipse(x,y-7,4,4,'#c4a575');}}
193	      // Market awnings and café tables identify working destinations at a glance.
194	      for(let i=0;i<4;i++){const x=840+i*48,y=1070;this.rect(x,y,40,16,'#615d42');this.rect(x-3,y-20,46,22,i%2?'#bd8b59':'#668568');for(let k=0;k<4;k++)this.rect(x-3+k*12,y-20,6,22,'#e3d0a3');}
195	      for(const x of [685,775]){this.ellipse(x,956,12,8,'#755f3f');this.ellipse(x,956,10,6,'#d6bd84');for(const dx of [-18,18])this.rect(x+dx-3,953,6,8,'#646a48');}
196	      if(night){
197	        this.rect(0,0,C.WIDTH,C.HEIGHT,'#091c3d83');
198	        for(const lamp of [{x:335,y:610},{x:566,y:705},{x:867,y:473},{x:777,y:923},{x:1293,y:1030},{x:1535,y:934}]){
199	          const glow=c.createRadialGradient(lamp.x,lamp.y,0,lamp.x,lamp.y,66);glow.addColorStop(0,'#eab85a3d');glow.addColorStop(1,'#eab85a00');
200	          this.rect(lamp.x-66,lamp.y-66,132,132,glow);this.line([[lamp.x,lamp.y+9],[lamp.x,lamp.y-14]],'#293e3e',3);this.ellipse(lamp.x,lamp.y-16,5,6,'#f0cd84');
201	        }
202	      }
203	      if(view.path&&view.path.length){
204	        // A dark underlay keeps the warm route dashes readable on every surface.
205	        const routePoints=[[view.position.x,view.position.y],...view.path.map(p=>[p.x,p.y])];
206	        c.setLineDash([10,9]);c.lineDashOffset=-t*12;
207	        this.line(routePoints,'#102c385c',8);this.line(routePoints,'#f6d88f',5);
208	        c.setLineDash([]);c.lineDashOffset=0;
209	      }
210	      if(view.garden&&!night){
211	        const e=window.FlowerNetwork.ENTRY;
212	        this.rect(e.x-30,e.y-45,60,28,'#72917b');this.rect(e.x-20,e.y-40,40,20,'#b9d6c0');
213	        this.line([[e.x-30,e.y-45],[e.x,e.y-59],[e.x+30,e.y-45]],'#3f6350',4);
214	        this.text(view.garden.known?'温室侧门':'玻璃屋后的门',e.x,e.y+20,14,'#294b51','sans-serif');
215	        if(!view.garden.pump)this.ellipse(e.x+20,e.y-4,20,8,'#527f8b');
216	        const cart=view.flowerCart;if(cart){this.rect(cart.x-14,cart.y-7,28,16,'#927752');this.ellipse(cart.x-12,cart.y+10,5,5,'#294b51');this.ellipse(cart.x+12,cart.y+10,5,5,'#294b51');this.tulips(cart.x,cart.y-8,{palette:'mixed',wrap:'paper'},.8);this.text('搬花车',cart.x,cart.y-32,12,'#294b51','sans-serif');}
217	      }
218	      const p=view.position;
219	      for(const place of Object.values(C.PLACES)){
220	        const active=view.target===place.id||view.mode==='place'&&view.place===place.id,known=p.visited.includes(place.id);
221	        const distance=Math.hypot(place.x-p.x,place.y-p.y);
222	        // Close street view labels only the door you are near (or walking to);
223	        // the overview keeps all seven destination labels.
