      c.save();c.beginPath();c.rect(57,64,366,292);c.clip();
      const sky=c.createLinearGradient(0,65,0,290);sky.addColorStop(0,night?'#142e42':'#aac9c8');sky.addColorStop(1,night?'#627b7e':'#ede0b4');
      this.rect(57,64,366,292,sky);
