1	'use strict';
2	
3	// PLAY04 canal street atmosphere regressions. The harness is a recording
4	// Canvas2D context inside a VM: a real save/restore stack, a real transform
5	// matrix, effective styles logged per call and stable gradient handles.
6	const { test } = require('node:test');
7	const assert = require('node:assert/strict');
8	const fs = require('node:fs');
9	const path = require('node:path');
10	const vm = require('node:vm');
11	
12	const City = require(path.join(__dirname, 'reopening-city.js'));
13	const scenePath = path.join(__dirname, 'reopening-scene.js');
14	assert.ok(fs.existsSync(scenePath), 'reopening-scene.js must exist');
15	const sceneSource = fs.readFileSync(scenePath, 'utf8');
16	
17	// One shared media-query result so individual tests can flip reduced motion.
18	const mediaQuery = { matches: false };
19	
20	function loadWorld() {
21	  const sandbox = {};
22	  sandbox.window = sandbox; // window.City / window.PubScene resolve on the VM global
23	  sandbox.City = City;
24	  sandbox.devicePixelRatio = 1;
25	  sandbox.matchMedia = () => mediaQuery;
26	  vm.createContext(sandbox);
27	  vm.runInContext(sceneSource, sandbox);
28	  return sandbox;
29	}
30	
31	// Required finite-number argument positions per Canvas operation. fillText
32	// and strokeText receive their text at index 0; addColorStop a color string.
33	const NUMERIC_INDICES = {
