36	  moveTo: [0, 1], lineTo: [0, 1],
37	  quadraticCurveTo: [0, 1, 2, 3], bezierCurveTo: [0, 1, 2, 3, 4, 5],
38	  fillText: [1, 2], strokeText: [1, 2],
39	  translate: [0, 1], scale: [0, 1], rotate: [0],
40	  transform: [0, 1, 2, 3, 4, 5], setTransform: [0, 1, 2, 3, 4, 5],
41	  createRadialGradient: [0, 1, 2, 3, 4, 5], createLinearGradient: [0, 1, 2, 3],
42	  addColorStop: [0]
43	};
44	const TEXT_METHODS = new Set(['fillText', 'strokeText']);
45	// Argument pair holding the anchor point projected through the live matrix.
46	const XY_ORIGIN = {
47	  fillRect: [0, 1], clearRect: [0, 1], rect: [0, 1],
48	  ellipse: [0, 1], arc: [0, 1], arcTo: [0, 1],
49	  moveTo: [0, 1], lineTo: [0, 1],
50	  quadraticCurveTo: [0, 1], bezierCurveTo: [0, 1],
51	  fillText: [1, 2], strokeText: [1, 2]
52	};
53	
54	function createRecorder() {
55	  const calls = [];
56	  const stack = [];
57	  let matrix = [1, 0, 0, 1, 0, 0];
58	  let gradientSeq = 0;
59	  const style = {
60	    fillStyle: '#000000', strokeStyle: '#000000', lineWidth: 1,
61	    font: '10px sans-serif', textAlign: 'start', lineDash: [], lineDashOffset: 0
62	  };
63	
64	  function screen(x, y) {
65	    return [
66	      matrix[0] * x + matrix[2] * y + matrix[4],
67	      matrix[1] * x + matrix[3] * y + matrix[5]
68	    ];
69	  }
70	  function tag(value) {
71	    return value && typeof value === 'object' && '__gid' in value ? { gradient: value.__gid } : value;
72	  }
73	  function record(name, args) {
74	    const required = NUMERIC_INDICES[name];
75	    if (required) {
76	      for (const index of required) {
77	        const value = args[index];
78	        assert.ok(
79	          typeof value === 'number' && Number.isFinite(value),
80	          name + ' requires finite numeric geometry at argument ' + index + ' but got ' + String(value)
81	        );
82	      }
83	    }
84	    if (TEXT_METHODS.has(name)) {
85	      assert.ok(typeof args[0] === 'string', name + ' first argument must be the text to draw');
86	    } else if (name === 'addColorStop') {
87	      assert.ok(typeof args[1] === 'string', 'addColorStop color must be a string');
88	    }
89	    for (const value of args) {
90	      if (typeof value === 'number') {
91	        assert.ok(Number.isFinite(value), name + ' received a non-finite number');
92	      }
93	    }
94	    let projected = null;
95	    const origin = XY_ORIGIN[name];
96	    if (origin) {
97	      const [sx, sy] = screen(args[origin[0]], args[origin[1]]);
98	      assert.ok(Number.isFinite(sx) && Number.isFinite(sy), name + ' produced non-finite screen coordinates');
99	      projected = [sx, sy];
100	    }
101	    for (const v of matrix) assert.ok(Number.isFinite(v), name + ' corrupted the transform matrix');
102	    calls.push({
103	      name,
104	      args: args.map(tag),
105	      fillStyle: tag(style.fillStyle),
106	      strokeStyle: tag(style.strokeStyle),
107	      lineWidth: style.lineWidth,
108	      font: style.font,
109	      textAlign: style.textAlign,
110	      lineDash: style.lineDash.slice(),
111	      lineDashOffset: style.lineDashOffset,
112	      screen: projected,
113	      matrix: matrix.slice()
114	    });
115	  }
116	
117	  function gradient(id) {
118	    return { __gid: id, addColorStop(offset, color) { record('addColorStop', [offset, color]); } };
119	  }
120	
121	  const explicit = {
122	    save() {
123	      stack.push({ matrix: matrix.slice(), style: { ...style, lineDash: style.lineDash.slice() } });
124	      record('save', []);
125	    },
126	    restore() {
127	      const previous = stack.pop();
128	      assert.ok(previous, 'ctx.restore() called without a matching ctx.save()');
129	      matrix = previous.matrix;
130	      Object.assign(style, previous.style);
131	      record('restore', []);
132	    },
133	    translate(x, y) {
134	      matrix[4] += matrix[0] * x + matrix[2] * y;
135	      matrix[5] += matrix[1] * x + matrix[3] * y;
136	      record('translate', [x, y]);
137	    },
138	    scale(sx, sy) {
139	      // Canvas post-multiplication: scale the x column (a,b) by sx and the
140	      // y column (c,d) by sy; the accumulated translation (e,f) stays fixed.
141	      matrix[0] *= sx; matrix[1] *= sx;
142	      matrix[2] *= sy; matrix[3] *= sy;
143	      record('scale', [sx, sy]);
144	    },
145	    setLineDash(dash) {
146	      const value = Array.isArray(dash) ? dash.slice() : [];
147	      for (const entry of value) {
148	        assert.ok(typeof entry === 'number' && Number.isFinite(entry), 'setLineDash entries must be finite numbers');
149	      }
150	      style.lineDash = value;
151	      record('setLineDash', value.slice());
152	    },
153	    createRadialGradient(x0, y0, r0, x1, y1, r1) {
154	      record('createRadialGradient', [x0, y0, r0, x1, y1, r1]);
155	      return gradient(++gradientSeq);
156	    },
157	    createLinearGradient(x0, y0, x1, y1) {
158	      record('createLinearGradient', [x0, y0, x1, y1]);
159	      return gradient(++gradientSeq);
160	    }
161	  };
162	
163	  const ctx = new Proxy(explicit, {
164	    get(target, key) {
165	      if (typeof key === 'symbol') return undefined;
166	      if (key in target) return target[key];
167	      return (...args) => record(String(key), args);
168	    },
169	    set(target, key, value) {
170	      if (key === 'lineDashOffset') {
171	        assert.ok(Number.isFinite(value), 'lineDashOffset must stay finite');
172	      }
173	      style[key] = value;
174	      return true;
175	    }
176	  });
177	
178	  return {
179	    ctx,
180	    calls,
181	    depth: () => stack.length,
182	    matrix: () => matrix.slice(),
183	    dash: () => style.lineDash.slice(),
184	    offset: () => style.lineDashOffset
185	  };
186	}
