        for(let i=0;i<8;i++){const x=park.x+25+(i%4)*(park.w-50)/3,y=park.y+25+Math.floor(i/4)*(park.h-50);this.ellipse(x+4,y+6,15,18,'#425a4845');this.ellipse(x,y,14,19,i%2?'#527655':'#6c865c');this.ellipse(x-4,y-5,8,11,'#94a776');}
      }
